mapper.select:
SELECT ID, APPLY_NO, APPLICANT, APPLY_TIME, USER_O_CODE, USER_O_NAME, ACCOUNT, ORG, FINANCIER, ENABLED, TEL, EMAIL, MOBILE, STATUS, CURRENT_APPROVER, APPROVE_START_TIME, APPROVE_END_TIME, REMARK, CREATE_TIME, UPDATE_TIME FROM SYS_RBAC_USER_APPLY
AND APPLY_NO LIKE '%' || #{applyNo} || '%'
AND APPLICANT = #{applicant}
AND STATUS = #{status}
ORDER BY APPLY_TIME DESC
